574	static smc_idma_des *__mci_prepare_dma(struct mmc_host *host, struct mmc_data *data)
575	{
576		uint32_t temp;
577		smc_idma_des *pdes = NULL;
578	
579		/* creat descriptor list, two mode: 1-fixed skip length, 2-chain mode */
580		pdes = __mci_alloc_idma_des(host, data);
581		if (NULL == pdes) {
582			SDC_LOGW("alloc IDMA descriptor failed\n");
583			return NULL;
584		}
585	
586		temp = mci_readl(host, SDXC_REG_GCTRL);
587		temp |= SDXC_DMAEnb;
588		mci_writel(temp, host, SDXC_REG_GCTRL);
589		temp |= (SDXC_DMAReset | SDXC_FIFOReset);
590		mci_writel(temp, host, SDXC_REG_GCTRL);
591		__mci_check_bit_clear(host, SDXC_REG_GCTRL, (SDXC_DMAReset | SDXC_FIFOReset));
592		mci_writel(SDXC_IDMACSoftRST, host, SDXC_REG_DMAC); /* reset IDMAC */
593		__mci_check_bit_clear(host, SDXC_REG_DMAC, SDXC_IDMACSoftRST);
594		temp = SDXC_IDMACFixBurst | SDXC_IDMACIDMAOn;
595		mci_writel(temp, host, SDXC_REG_DMAC);
596		/* enable IDMA interrupt, here not use */
597		temp = mci_readl(host, SDXC_REG_IDIE);
598		temp &= ~(SDXC_IDMACReceiveInt | SDXC_IDMACTransmitInt);
599		if (data->flags & MMC_DATA_WRITE) {
600			;//temp |= SDXC_IDMACTransmitInt; /* disable dma int for less irqs */
601		} else {
602			temp |= SDXC_IDMACReceiveInt;
603		}
604		mci_writel(temp, host, SDXC_REG_IDIE);
605	
606		/* write descriptor address to register */
607		mci_writel(SDXC_IDMAC_DES_ADDR((uint32_t)MEMS_VA2PA(HAL_PT_TO_U(pdes))), host, SDXC_REG_DLBA);
608		/* write water level */
609		mci_writel((BURST_SIZE << 28) | (SMC_RX_WLEVEL << 16) | SMC_TX_WLEVEL,
610		       host, SDXC_REG_FTRGL);
611	
612		return pdes;
613	}
