int PlayerStop(Player* pl)      //* media stream information is still kept by the player.
{
    PlayerContext* p;
    int            ret;
    logd("****** PlayerStop");
    p = (PlayerContext*)pl;

    if(p->eStatus == PLAYER_STATUS_STOPPED)
    {
        /* 切歌/播放完成等场景下 Player 状态可能已是 STOPPED，但声卡设备
         * 可能尚未真正关闭（audioRender 组件未收到 stop 消息）。若此处直接
         * 返回，AudioRenderCompStop 永不执行 → 底层 substream ref_count 不
         * 归零 → 后续 aplay/新歌 open 报 -16 EBUSY → 切歌无声（8-6 Part6
         * 实证：退出播放器后再 aplay 报 -16）。故 STOPPED 时也强制关闭
         * 音频渲染组件（其内部 SoundDeviceStop/dm_sound_stop 对空 handle
         * 幂等安全）。 */
        logw("player already stopped, force stop audio render to release sound device.");
#if !CONFIG_ONLY_DISABLE_AUDIO
        if(p->pAudioRender != NULL)
            AudioRenderCompStop(p->pAudioRender);
#endif
        return -1;
    }

