/*
 * 遍历 RIFF chunk 查找 fmt / data chunk。
 * 很多工具生成的 WAV 在 "WAVE" 之后、fmt 之前带 JUNK/LIST chunk
 * （用于对齐/元数据），固定 44 字节 wav_header_t 解析会错位 → 读出的
 * channels/rate/bits 全 0 → hw_params format invalid (-14)。
 * 返回 0 成功；fmt 缺失/RIFF 头不对返回 -1。
 */
static int parse_wav_chunks(int fd, wav_hw_params_t *hwparams,
                            unsigned int *data_size)
{
	unsigned char hdr[12];
	ssize_t r;

	r = read(fd, hdr, sizeof(hdr));
	if (r != (ssize_t)sizeof(hdr))
		return -1;
	if (memcmp(hdr, "RIFF", 4) != 0 || memcmp(hdr + 8, "WAVE", 4) != 0)
		return -1;

	for (;;) {
		unsigned char chunk[8];
		unsigned int csize;
		unsigned char fmtdata[40];

		r = read(fd, chunk, sizeof(chunk));
		if (r != (ssize_t)sizeof(chunk))
			break;

		csize = chunk[4] | (chunk[5] << 8) |
			(chunk[6] << 16) | (chunk[7] << 24);

		if (memcmp(chunk, "fmt ", 4) == 0) {
			unsigned int fsize = csize > sizeof(fmtdata) ?
				sizeof(fmtdata) : csize;
			unsigned short audio_format, channels, block_align, bits;
			unsigned int sample_rate;

			r = read(fd, fmtdata, fsize);
			if (r != (ssize_t)fsize)
				return -1;
			if (csize > fsize)
				lseek(fd, csize - fsize, SEEK_CUR);

			audio_format = fmtdata[0] | (fmtdata[1] << 8);
			channels     = fmtdata[2] | (fmtdata[3] << 8);
			sample_rate  = fmtdata[4] | (fmtdata[5] << 8) |
				(fmtdata[6] << 16) | (fmtdata[7] << 24);
			block_align  = fmtdata[12] | (fmtdata[13] << 8);
			bits         = fmtdata[14] | (fmtdata[15] << 8);

			hwparams->channels = channels;
			hwparams->rate = sample_rate;
			hwparams->format = SND_PCM_FORMAT_UNKNOWN;
			switch (bits) {
			case 8:
				hwparams->format = SND_PCM_FORMAT_U8;
				break;
			case 16:
				hwparams->format = SND_PCM_FORMAT_S16_LE;
				break;
			case 24:
				if (channels && (block_align / channels) == 4)
					hwparams->format = SND_PCM_FORMAT_S24_LE;
				break;
			case 32:
				hwparams->format = SND_PCM_FORMAT_S32_LE;
				break;
			default:
				break;
			}
			/* 仅支持 PCM 线性格式 */
			if (audio_format != WAV_FMT_PCM) {
				syslog(LOG_ERR,"unsupported wav audio format 0x%x\n",
					audio_format);
				return -1;
			}
			if (hwparams->format == SND_PCM_FORMAT_UNKNOWN) {
				syslog(LOG_ERR,"unsupported wav bits %u\n", bits);
				return -1;
			}
		} else if (memcmp(chunk, "data", 4) == 0) {
			*data_size = csize;
			return 0;
		} else {
			/* JUNK/LIST 等未知 chunk，跳过（RIFF 内 chunk 偶对齐） */
			lseek(fd, csize + (csize & 1), SEEK_CUR);
		}
	}

	return -1;
}

static int play_fs_music(audio_mgr_t *mgr, const char *path)
{
	int ret = 0, fd = 0;
	wav_header_t wav_header;
	wav_hw_params_t wav_hwparams = {16000, SND_PCM_FORMAT_UNKNOWN, 2};
	unsigned int c, written = 0, count = UINT_MAX;
	unsigned int chunk_bytes, frame_bytes = 0;
	ssize_t r = 0;
	audio_mgr_t *audio_hpcm_mgr = NULL;
	char *audiobuf = NULL;

	fd = open(path, O_RDONLY);
	if (fd < 0) {
		syslog(LOG_INFO,"no such wav file\n");
		return -1;
	}
	/* mode 0:wav 1:pcm */
	if (g_playback_mode == 0) {
		count = UINT_MAX;
		if (parse_wav_chunks(fd, &wav_hwparams, &count) != 0) {
			syslog(LOG_ERR,"check wav header failed\n");
			goto err_check_wav_header;
		}
	}

