播放循环：
```c
if (wav24) {
    // packed 24-bit → 16-bit 降转
    int nsamp = r / 3;
    const uint8_t *src = audiobuf;
    int16_t *dst = (int16_t *)audiobuf;  // 就地转换（nsamp*2 < r）
    for (i = 0; i < nsamp; i++) {
        int32_t v = src[0] | (src[1]<<8) | (src[2]<<16);
        if (v & 0x800000) v |= ~0xFFFFFF;
        dst[i] = (int16_t)(v >> 8);
        src += 3;
    }
    r = nsamp * 2;
