        for (i = 0; i < nsamp; i++) {
            int32_t v = src[0] | (src[1] << 8) | (src[2] << 16);
            if (v & 0x800000)
                v |= ~0xFFFFFF;
            conv16[i] = (int16_t)(v >> 8);
            src += 3;
