=== 降转循环 written/c 账目检查 ===
	while (written < count) {
		c = count - written;
		if (c > chunk_bytes)
			c = chunk_bytes;
		r = read(fd, audiobuf, c);
		if (r < 0 || r != c) {
			syslog(LOG_ERR,"read file error, r=%ld,c=%u\n", (long int)r, c);
			break;
		}
		if (packed24) {
			/* packed 24-bit（3B/样本）→ 16-bit 软件降转，就地转换
			 * （2B 输出 ≤ 3B 输入，缓冲安全）。 */
			int nsamp = (int)(r / 3);   /* 样本数 = 帧 × 通道 */
			int i;
			uint8_t *src = (uint8_t *)audiobuf;
			int16_t *dst = (int16_t *)audiobuf;
			for (i = 0; i < nsamp; i++) {
				int32_t v = src[0] | (src[1] << 8) | (src[2] << 16);
				if (v & 0x800000)
					v |= ~0xFFFFFF;   /* 24-bit 符号扩展 */
				dst[i] = (int16_t)(v >> 8);
				src += 3;
			}
			r = nsamp * 2;   /* 降转后 16-bit 字节数 */
			c = (unsigned int)r;
		}
		r = pcm_write(mgr->handle, audiobuf, r/frame_bytes, frame_bytes);
		if (r != c/frame_bytes)
			break;
		written += c;
	}
	snd_vela_pcm_drain(mgr->handle);

	free(audiobuf);

input.new_string:
if (packed24) {
	/* packed 24-bit（3B/样本）→ 16-bit 软件降转，就地转换
	 * （2B 输出 ≤ 3B 输入，缓冲安全）。
	 * 注意：written/count 以【源文件 24-bit 字节数】为账目，
	 * 降转只改变送入 pcm_write 的帧数，不改变文件读取进度。 */
	int nsamp = (int)(r / 3);   /* 样本数 = 帧 × 通道 */
	int i;
	uint8_t *src = (uint8_t *)audiobuf;
	int16_t *dst = (int16_t *)audiobuf;
	for (i = 0; i < nsamp; i++) {
		int32_t v = src[0] | (src[1] << 8) | (src[2] << 16);
		if (v & 0x800000)
			v |= ~0xFFFFFF;   /* 24-bit 符号扩展 */
		dst[i] = (int16_t)(v >> 8);
		src += 3;
	}
	/* c 保持原 24-bit 读取字节数（written/count 账目不变） */
	r = pcm_write(mgr->handle, audiobuf,
		      (nsamp * 2) / frame_bytes, frame_bytes);
	if (r != (nsamp * 2) / (int)frame_bytes)
		break;
} else {
	r = pcm_write(mgr->handle, audiobuf, r/frame_bytes, frame_bytes);
	if (r != c/frame_bytes)
		break;
}
written += c;

